  $('zin').onclick = () => zoomAt(vb[0] + vb[2] / 2, vb[1] + vb[3] / 2, 0.6);
  $('zout').onclick = () => zoomAt(vb[0] + vb[2] / 2, vb[1] + vb[3] / 2, 1.6);
